package com.srent.contract;
import com.srent.audit.AuditService; import com.srent.booking.*; import com.srent.common.ApiException; import com.srent.security.CurrentUser; import com.srent.storage.StorageService; import com.srent.user.User; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.apache.pdfbox.Loader; import org.apache.pdfbox.text.PDFTextStripper; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/contracts") @RequiredArgsConstructor
public class ContractController {
    private final ContractRepository contracts;private final BookingRepository bookings;private final ContractAnalysisRepository analyses;private final ContractRiskItemRepository risks;private final StorageService storage;private final ContractAnalysisProvider provider;private final AuditService audit;
    public record CreateRequest(@NotNull UUID bookingId,@NotBlank @Size(max=180)String title){}public record UploadRequest(@NotBlank String contentType){}public record ContractResponse(UUID id,UUID bookingId,String title,Contract.Status status,String downloadUrl){static ContractResponse from(Contract c,String u){return new ContractResponse(c.getId(),c.getBooking().getId(),c.getTitle(),c.getStatus(),u);}}public record RiskResponse(String category,String severity,String explanation,String excerpt,String suggestedQuestion){}public record AnalysisResponse(UUID id,String provider,boolean simulated,String disclaimer,ContractAnalysis.ReviewStatus reviewStatus,String adminNote,List<RiskResponse>risks){}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public ContractResponse create(@Valid @RequestBody CreateRequest q){var b=bookings.findById(q.bookingId()).orElseThrow(()->ApiException.notFound("Booking"));access(b);if(b.getStatus()!=Booking.Status.ACCEPTED&&b.getStatus()!=Booking.Status.COMPLETED)throw ApiException.conflict("INVALID_BOOKING_STATE","Booking chưa đủ điều kiện tạo hợp đồng");if(contracts.existsByBookingId(b.getId()))throw ApiException.conflict("CONTRACT_EXISTS","Booking đã có hợp đồng");var c=new Contract();c.setBooking(b);c.setTitle(q.title());contracts.save(c);audit.log(CurrentUser.id(),"CONTRACT_CREATED","CONTRACT",c.getId(),null);return ContractResponse.from(c,null);}
    @PostMapping("/{id}/upload") @Transactional public StorageService.Upload upload(@PathVariable UUID id,@Valid @RequestBody UploadRequest q){if(!q.contentType().equals("application/pdf"))throw ApiException.badRequest("PDF_REQUIRED","Hợp đồng phải là PDF");var c=contractAccess(id);String key="contracts/"+c.getId()+"/"+UUID.randomUUID()+".pdf";c.setObjectKey(key);c.setContentType(q.contentType());c.setStatus(Contract.Status.UPLOADED);return storage.presignedUpload(true,key,q.contentType());}
    @PostMapping("/{id}/analyze") @Transactional public AnalysisResponse analyze(@PathVariable UUID id){var c=contractAccess(id);if(c.getObjectKey()==null)throw ApiException.conflict("CONTRACT_NOT_UPLOADED","Chưa upload hợp đồng");storage.stat(true,c.getObjectKey());String text=extract(c.getObjectKey());var result=provider.analyze(text);var a=analyses.findByContractId(id).orElseGet(()->{var x=new ContractAnalysis();x.setContract(c);return x;});a.setProvider(provider.name());a.setSimulated(provider.simulated());a.setDisclaimer((provider.simulated()?"Kết quả mô phỏng. ":"")+"AI chỉ hỗ trợ rà soát, không phải kết luận hoặc tư vấn pháp lý chính thức");a.setReviewStatus(ContractAnalysis.ReviewStatus.PENDING);analyses.save(a);risks.deleteAllByAnalysisId(a.getId());for(var x:result.risks()){var r=new ContractRiskItem();r.setAnalysis(a);r.setCategory(x.category());r.setSeverity(x.severity());r.setExplanation(x.explanation());r.setExcerpt(x.excerpt());r.setSuggestedQuestion(x.suggestedQuestion());risks.save(r);}c.setStatus(Contract.Status.ANALYZED);audit.log(CurrentUser.id(),"CONTRACT_ANALYZED","CONTRACT",id,"provider="+provider.name());return analysisResponse(a);}
    @GetMapping("/{id}") @Transactional(readOnly=true) public ContractResponse one(@PathVariable UUID id){var c=contractAccess(id);return ContractResponse.from(c,c.getObjectKey()==null?null:storage.presignedDownload(c.getObjectKey()));}
    @GetMapping("/{id}/analysis") @Transactional(readOnly=true) public AnalysisResponse analysis(@PathVariable UUID id){var c=contractAccess(id);var a=analyses.findByContractId(c.getId()).orElseThrow(()->ApiException.notFound("Phân tích hợp đồng"));if(c.getBooking().getStudent().getId().equals(CurrentUser.id())&&a.getReviewStatus()!=ContractAnalysis.ReviewStatus.PUBLISHED)throw ApiException.forbidden("Kết quả đang chờ Admin kiểm duyệt");return analysisResponse(a);}
    private Contract contractAccess(UUID id){var c=contracts.findById(id).orElseThrow(()->ApiException.notFound("Hợp đồng"));access(c.getBooking());return c;}private void access(Booking b){UUID u=CurrentUser.id();if(!b.getStudent().getId().equals(u)&&!b.getLandlord().getId().equals(u)&&CurrentUser.principal().role()!=User.Role.ADMIN)throw ApiException.forbidden("Không có quyền truy cập hợp đồng");}
    private AnalysisResponse analysisResponse(ContractAnalysis a){return new AnalysisResponse(a.getId(),a.getProvider(),a.isSimulated(),a.getDisclaimer(),a.getReviewStatus(),a.getAdminNote(),risks.findAllByAnalysisId(a.getId()).stream().map(x->new RiskResponse(x.getCategory(),x.getSeverity(),x.getExplanation(),x.getExcerpt(),x.getSuggestedQuestion())).toList());}
    private String extract(String key){try(var in=storage.readPrivate(key);var doc=Loader.loadPDF(in.readAllBytes())){String t=new PDFTextStripper().getText(doc);return t.length()>100000?t.substring(0,100000):t;}catch(Exception e){throw ApiException.badRequest("PDF_READ_ERROR","Không thể trích xuất nội dung PDF");}}
}
